const aiResponse = $input.first().json.text;
let replyText = aiResponse;
let newWorkouts = null;
let newCoachNotes = null;

const jsonRegex = /```(?:json)?\s*([\s\S]*?)\s*```/g;
let match;
let foundBlock = false;

while ((match = jsonRegex.exec(aiResponse)) !== null) {
    foundBlock = true;
    try {
        const parsed = JSON.parse(match[1]);
        if (parsed.new_workouts) {
            newWorkouts = parsed.new_workouts;
            replyText = replyText.replace(match[0], '');
        }
        if (parsed.update_coach_notes) {
            newCoachNotes = parsed.update_coach_notes;
            replyText = replyText.replace(match[0], '');
        }
    } catch (e) {}
}

if (!foundBlock) {
    let fallbackMatch = aiResponse.match(/(\{[\s\S]*"(?:new_workouts|update_coach_notes)"[\s\S]*\})/);
    if (fallbackMatch) {
        try {
            const parsed = JSON.parse(fallbackMatch[1]);
            if (parsed.new_workouts) {
                newWorkouts = parsed.new_workouts;
                replyText = replyText.replace(fallbackMatch[0], '');
            }
            if (parsed.update_coach_notes) {
                newCoachNotes = parsed.update_coach_notes;
                replyText = replyText.replace(fallbackMatch[0], '');
            }
        } catch (e) {}
    }
}

let finalReply = replyText.trim();
if (finalReply.length > 4000) {
    finalReply = finalReply.substring(0, 4000) + '\n\n...[Message truncated by AI Coach]';
}

return {
    replyText: finalReply,
    newWorkouts: newWorkouts,
    newCoachNotes: newCoachNotes,
    athleteId: $('Code Prepare Prompt').item.json.athleteId,
    userMessage: $('Code Prepare Prompt').item.json.userMessage
};

