const data = $input.first().json;
const userMessage = $('Telegram Trigger').item.json.message.text;

// Format the History
let historyText = "";
if (data.history) {
    data.history.reverse().forEach(msg => {
        historyText += `${msg.role.toUpperCase()}: ${msg.content}\n`;
    });
}

// Build the System Prompt
const systemPrompt = `You are an elite endurance coach.

### ATHLETE PROFILE
Metrics: ${JSON.stringify(data.athlete.metrics || {})}
Coach Notes: ${data.athlete.coach_notes || 'None'}

### CURRENT STATE
Active Goal: ${data.active_goal ? data.active_goal.description : 'No active goal set.'}

### RECENT CONTEXT
Completed Activities: ${JSON.stringify(data.activities || [])}
Planned Workouts: ${JSON.stringify(data.workouts || [])}

### INSTRUCTIONS
CRITICAL RULES:
1. Keep your conversational response extremely short and concise (under 150 words). Do not write long essays.
2. If you generate workouts, ONLY generate for the immediate next 7 days. Never generate weeks in advance.
3. If you output JSON, you MUST wrap it strictly in \`\`\`json markdown blocks with exact keys!

If you need to generate new workouts, output EXACTLY this format:
\`\`\`json
{"new_workouts": [{"scheduled_date": "YYYY-MM-DD", "sport_type": "Run", "description": "...", "target_duration_mins": 45}]}
\`\`\`

If you need to remember a constraint, output EXACTLY this format:
\`\`\`json
{"update_coach_notes": "..."}
\`\`\`

### HISTORY
${historyText}`;

return {
    systemPrompt: systemPrompt,
    userMessage: userMessage,
    athleteId: data.athlete.id
};

const workouts = $input.first().json.newWorkouts;
const athleteId = $input.first().json.athleteId;

if (!workouts || workouts.length === 0) return [];

return workouts.map(workout => {
    return {
        json: {
            athleteId: athleteId,
            scheduled_date: workout.scheduled_date || workout.scheduleddate || new Date().toISOString().split('T')[0],
            sport_type: workout.sport_type || workout.sporttype || 'Run',
            title: workout.title || workout.sport_type || workout.sporttype || 'Workout',
            description: workout.description || 'Workout planned by AI Coach',
            target_duration_mins: workout.target_duration_mins || workout.targetdurationmins || 60
        }
    };
});

